def format_wait_time(seconds: float) -> str:
  minutes = int(seconds / 60)
  if minutes < 1:
      return "less than a minute"
  elif minutes == 1:
      return "about 1 minute"
  elif minutes < 5:
      return f"about {minutes} minutes"
  elif minutes < 10:
      return "5 to 10 minutes"
  else:
      return "more than 10 minutes"

